        pane.append(table([{ h: '#', r: 1 }, { h: 'code' }, { h: 'player' }, { h: 'G', r: 1 }, { h: 'A', r: 1 }, { h: 'P', r: 1 }, { h: 'SOG', r: 1 }, { h: 'ixG', r: 1 }, { h: 'TOI', r: 1 }], t.skaters.filter((r) => r.toi || r.pts || r.sog).map((r) => [r.jersey, r.code, r.name, r.g, r.a, r.pts, r.sog, f3(r.ixg), mmss(r.toi)])));
